import { Component, ElementRef, ViewChild, AfterViewInit, Output, EventEmitter, Input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms'; // ← AÑADE ESTA IMPORTACIÓN

@Component({
  selector: 'app-firma-modal',
  templateUrl: './firma-modal.component.html',
  styleUrls: ['./firma-modal.component.less'],
  standalone: true, // ← SI ES STANDALONE
  imports: [ // ← AÑADE ESTA PROPIEDAD imports
    CommonModule,
    FormsModule // ← AÑADE FormsModule AQUÍ
  ]
})
export class FirmaModalComponent implements AfterViewInit {
  @ViewChild('firmaCanvas', { static: false }) canvasRef!: ElementRef;
  @Output() firmaGuardada = new EventEmitter<string>();
  @Output() modalCerrado = new EventEmitter<void>();
  @Input() mostrarModal: boolean = false;

  private canvas!: HTMLCanvasElement;
  private ctx!: CanvasRenderingContext2D;
  private estaDibujando = false;
  private ultimoX = 0;
  private ultimoY = 0;
  private historial: ImageData[] = [];

  // Configuración
  colorFirma = '#000000';
  grosorLinea = 2;
  firmaDataURL: string | null = null;
  puedeDeshacer = false;

  ngAfterViewInit() {
    this.inicializarCanvas();
  }

  private inicializarCanvas() {
    this.canvas = this.canvasRef.nativeElement;
    this.ctx = this.canvas.getContext('2d')!;

    // Configuración inicial
    this.ctx.lineWidth = this.grosorLinea;
    this.ctx.lineCap = 'round';
    this.ctx.lineJoin = 'round';
    this.ctx.strokeStyle = this.colorFirma;

    // Listeners para dibujar
    this.canvas.addEventListener('mousedown', this.comenzarDibujo.bind(this));
    this.canvas.addEventListener('mousemove', this.dibujar.bind(this));
    this.canvas.addEventListener('mouseup', this.terminarDibujo.bind(this));
    this.canvas.addEventListener('mouseout', this.terminarDibujo.bind(this));

    // Para dispositivos táctiles
    this.canvas.addEventListener('touchstart', this.comenzarDibujoTouch.bind(this));
    this.canvas.addEventListener('touchmove', this.dibujarTouch.bind(this));
    this.canvas.addEventListener('touchend', this.terminarDibujo.bind(this));
  }

  private comenzarDibujo(e: MouseEvent) {
    this.estaDibujando = true;
    const rect = this.canvas.getBoundingClientRect();
    this.ultimoX = e.clientX - rect.left;
    this.ultimoY = e.clientY - rect.top;

    // Guardar estado para deshacer
    this.guardarEstado();
  }

  private comenzarDibujoTouch(e: TouchEvent) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousedown', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    this.canvas.dispatchEvent(mouseEvent);
  }

  private dibujar(e: MouseEvent) {
    if (!this.estaDibujando) return;

    const rect = this.canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    this.ctx.beginPath();
    this.ctx.moveTo(this.ultimoX, this.ultimoY);
    this.ctx.lineTo(x, y);
    this.ctx.stroke();

    this.ultimoX = x;
    this.ultimoY = y;

    // Actualizar vista previa
    this.actualizarVistaPrevia();
  }

  private dibujarTouch(e: TouchEvent) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousemove', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    this.canvas.dispatchEvent(mouseEvent);
  }

  private terminarDibujo() {
    this.estaDibujando = false;
  }

  limpiarFirma() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.firmaDataURL = null;
    this.historial = [];
    this.puedeDeshacer = false;
  }

  deshacer() {
    if (this.historial.length > 0) {
      const estadoAnterior = this.historial.pop()!;
      this.ctx.putImageData(estadoAnterior, 0, 0);
      this.puedeDeshacer = this.historial.length > 0;
      this.actualizarVistaPrevia();
    }
  }

  private guardarEstado() {
    const imageData = this.ctx.getImageData(0, 0, this.canvas.width, this.canvas.height);
    this.historial.push(imageData);
    this.puedeDeshacer = true;
  }



  private actualizarVistaPrevia() {
    this.firmaDataURL = this.canvas.toDataURL('image/png');
  }

  guardarFirma() {
    if (this.firmaDataURL) {
      // Convertir a base64 y enviar al componente padre
      this.firmaGuardada.emit(this.firmaDataURL);
      this.cerrarModal();
    }
  }

  cerrarModal() {
    this.limpiarFirma();
    this.modalCerrado.emit();
  }



  cambiarColor() {
    if (this.ctx) {
      this.ctx.strokeStyle = this.colorFirma;
    }
  }

  cambiarGrosor() {
    if (this.ctx) {
      this.ctx.lineWidth = this.grosorLinea;
    }
  }
}
